                    || (overriding_unwind_start.is_none()
                        && !self
                            .control
                            .exceptions
                            .active_exception_region_exclusions
                            .is_empty()
                        && self.control.withs.active_with_exits.is_empty()
                        && !self.control.exceptions.active_exception_handlers.is_empty());
